-- =====================================================
-- 安全隐患案例库 + 文书库拆分
-- 执行: python db/run_migrate.py
-- =====================================================

-- 1. 文书库加 region 字段
ALTER TABLE tb_hazard_knowledge
    ADD COLUMN IF NOT EXISTS region VARCHAR(50) DEFAULT '三明市' COMMENT '所属地区';

-- 2. 建案例库表
CREATE TABLE IF NOT EXISTS tb_hazard_case (
    id              BIGINT AUTO_INCREMENT PRIMARY KEY,
    category        VARCHAR(50)  NOT NULL COMMENT '隐患类别',
    title           VARCHAR(500) NOT NULL COMMENT '案例标题',
    description     TEXT         NOT NULL COMMENT '事故经过',
    severity        VARCHAR(10)  NOT NULL COMMENT '严重程度: 高/中/低',
    city            VARCHAR(50)  NOT NULL COMMENT '城市',
    district        VARCHAR(100) DEFAULT '' COMMENT '区/县',
    occurrence_date VARCHAR(20)  DEFAULT '' COMMENT '发生时间',
    casualties      VARCHAR(100) DEFAULT '' COMMENT '伤亡情况',
    cause           TEXT         COMMENT '事故原因',
    rectification   TEXT         COMMENT '整改措施',
    regulation_ref  TEXT         COMMENT '法规依据',
    source_url      VARCHAR(500) DEFAULT '' COMMENT '来源URL',
    verdict         TEXT         COMMENT '判决/处理结果',
    create_time     DATETIME     DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_category (category),
    INDEX idx_city (city),
    INDEX idx_severity (severity)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='安全隐患案例库（全国真实案例）';

-- 3. 插入种子案例（7类 × 6条 = 42条真实案例）
INSERT INTO tb_hazard_case (category, title, description, severity, city, district, occurrence_date, casualties, cause, rectification, regulation_ref, source_url, verdict) VALUES

-- ========== 消防安全 (6条) ==========
('消防安全', '重庆29楼电瓶车入户充电致2名邻居死亡', '周女士将电瓶车推至29楼家中阳台充电，夜间电气线路故障引发火灾，同楼层桂女士等2人因吸入大量浓烟身亡。灭火器过期、消防通道堵塞延误救援。', '高', '重庆市', '江北区', '2021-07-20', '2死', '电瓶车电气线路故障引燃周边可燃物；物业未能及时启动自动消防设施导致浓烟蔓延', '严禁电动自行车进楼入户充电；物业定期检查消防设施确保正常运转；设置集中充电桩并加装自动灭火装置', '《消防法》第28条：禁止在疏散通道、安全出口、楼梯间停放电动车或充电；《高层民用建筑消防安全管理规定》第37条', 'https://yk.lncourt.gov.cn/article/detail/2024/11/id/8234668.shtml', '周女士犯失火罪判刑3年；车主夫妇连带赔偿93万余元（70%）；物业赔偿36万余元（30%）'),

('消防安全', '湖北枣阳楼栋大厅电动车充电起火烧伤租户', '王某将电动车停放在一楼楼栋大厅充电，电动车突然起火蔓延至二楼，租户李某被烧伤住院8天，医疗费近9000元。大厅为居民唯一进出通道。', '中', '湖北枣阳市', '', '2024-08-01', '1伤', '电气故障引发火灾；充电设备处于夏季高温无人值守环境', '严禁在楼栋大厅、门厅等公共区域停放电动车或充电；安装智能充电桩具备自动断电功能；加强日常巡查', '《消防法》第28条；应急管理部《高层民用建筑消防安全管理规定》', 'https://sxszzy.shanxify.gov.cn/article/detail/2025/07/id/8913478.shtml', '车主王某承担70%责任赔偿14287元；房东承担次要责任'),

('消防安全', '南昌西湖区蓝天雅居电取暖器火灾致4死', '住户使用电取暖器，插接的移动排插电源线发生电热故障，引燃周边可燃物，被困人员发现起火晚，逃生通道被浓烟封堵。', '高', '江西南昌市', '西湖区', '2025-02-04', '4死', '户主私自将不同线径线路续接使用并插接大功率取暖设备；室内火灾荷载大；发现起火晚', '严禁私自改装电气线路；大功率电器应使用专用插座；安装独立式感烟火灾探测报警器；定期检查线路老化情况', '《消防法》第27条：电器产品、燃气用具的安装、使用及其线路设计、敷设必须符合消防技术标准', 'https://yjj.nc.gov.cn/', '成立市级事故调查组，发布正式调查报告'),

('消防安全', '河北承德养老院插排短路火灾致20死', '隆化县某养老院因插排短路引发火灾，火势迅速蔓延，造成重大人员伤亡。建筑内多为行动不便老人，疏散困难。', '高', '河北承德市', '隆化县', '2025-04-08', '20死', '插排短路引发火灾；养老机构消防设施不完善；人员疏散能力不足', '养老机构应安装电气火灾监控系统；定期检测电气线路；确保疏散通道畅通；配备无障碍疏散设施', '《消防法》第16条：单位消防安全职责；《养老机构消防安全管理规定》', '', '列为2025年重大安全生产事故，全国通报整改'),

('消防安全', '荣成市北车小区电气线路火灾（较大事故）', '小区居民楼因电气线路敷设和使用不当引发火灾，居民逃生自救能力不足，造成较大人员伤亡。', '高', '山东荣成市', '', '2025-09-14', '多人伤亡', '电气线路敷设和使用不当；居民逃生自救能力不足', '老旧小区应定期进行电气线路检测和改造；开展居民消防逃生演练；在楼道配备灭火器和应急照明', '《消防法》第16、28条；GB 50054《低压配电设计规范》', 'https://www.weihai.gov.cn/（威政字〔2025〕56号）', '威海市人民政府批复调查报告，认定为较大火灾事故'),

('消防安全', '深圳福田住宅电气线路故障火灾', '福田区某住宅小区住户内电气线路故障引发火灾，过火面积约30平方米，室内物品基本烧毁，无人员伤亡。火灾发生在凌晨，所幸住户察觉及时。', '中', '广东深圳市', '福田区', '2024-11-01', '无', '电气线路老化故障', '定期请专业电工检查室内线路；老旧住宅应更新配电箱和线路；安装漏电保护开关', '《消防法》第27条', 'https://gd.119.gov.cn/', '当事人自行承担财产损失，物业协助修复公共区域'),

-- ========== 建筑施工 (6条) ==========
('建筑施工', '深江铁路地面坍塌重大事故致13死', '深圳至江门铁路5标段施工现场，参建单位违规施工掘进引发掌子面上方局部塌方，异常工况处置时未能采取有效工程处理措施，导致地面坍塌。', '高', '广东深圳市', '宝安区', '2024-12-04', '13死', '违规施工掘进引发局部塌方；异常工况处置未能采取有效工程处理措施', '严格执行施工方案审批制度；建立异常工况应急处置预案；加强隧道施工监测预警；落实新奥法施工原则', '《安全生产法》第41条；《建设工程安全生产管理条例》第26条', 'https://yjgl.gd.gov.cn/', '广东省应急管理厅发布调查报告；参建单位被行政处罚，23名公职人员被追责，7名企业责任人被采取刑事强制措施'),

('建筑施工', '本溪工业厂房违规拆除坍塌致3死', '本溪市盛安建筑工程有限公司在工业厂房拆除作业中，未编制施工组织设计和专项施工方案，违规拆除一层间壁墙破坏了承重结构，导致建筑物失稳坍塌。', '高', '辽宁本溪市', '溪湖区', '2024-11-07', '3死', '未编制施工组织设计和专项施工方案；违规拆除间壁墙破坏承重结构', '拆除作业前必须编制专项施工方案并组织专家论证；严禁擅自拆除承重结构构件；进行结构安全评估后方可施工', '《建设工程安全生产管理条例》第26条；《建筑拆除工程安全技术规范》(JGJ 147)', 'https://yjj.benxi.gov.cn/', '施工技术员、项目经理被追究刑事责任；法定代表人被行政处罚；多名公职人员被移交纪委监委'),

('建筑施工', '围场钢结构立柱焊接不合格致立柱倒塌1死', '拌合站项目建设工地，钢结构立柱底板锚筋型号、焊接质量严重不符合设计和规范要求，受外力后柱底焊接节点断裂致立柱倾倒，作业人员随立柱坠落。', '高', '河北围场县', '', '2024-12-08', '1死', '钢结构立柱底板锚筋型号和焊接质量严重不符合设计和规范要求；施工人员违规作业', '钢结构焊接必须由持证焊工操作并进行无损检测；关键节点施工须有监理旁站；严格执行隐蔽工程验收制度', '《钢结构工程施工质量验收标准》(GB 50205)', 'https://www.weichang.gov.cn/art/2025/10/15/art_10285_1110731.html', '4人涉嫌重大责任事故罪被移送司法机关；道达尔公司被罚款50万元'),

('建筑施工', '深圳雪花科创城电梯井道脚手架坍塌致1死', '宝安区新安街道雪花科创城项目，电梯井道内脚手架搭设不规范，作业工人未按施工方案安装电梯钢梁，导致脚手架坍塌，工人坠落死亡。总承包中建六局未有效跟踪监督。', '高', '广东深圳市', '宝安区', '2024-03-31', '1死', '对专业分包单位统一协调管理不到位；未跟踪监督脚手架搭设；作业工人未按施工方案安装', '严格执行脚手架搭设验收制度；总承包单位必须对分包单位实施统一协调管理；落实危大工程旁站监理', '《建设工程安全生产管理条例》第24条；《危险性较大的分部分项工程安全管理规定》', 'http://zfcxjst.gd.gov.cn/xxgk/gsgg/content/post_4741767.html', '中建六局四公司被暂扣安全生产许可证30日，全国范围内不得承揽新项目'),

('建筑施工', '重庆万州检修平台坍塌致1死2伤', '万州新田港区二期工程1#钢煤棚，设备和检修平台失稳坍塌，作业人员从约5.5米高处坠落，造成1人死亡、2人受伤。', '高', '重庆市', '万州区', '2024-11-06', '1死2伤', '设备和检修平台失稳坍塌', '检修平台搭设前须进行承载力验算；高处作业必须系挂安全带并设置独立安全绳；建立设备设施定期巡检制度', '《安全生产法》第36条：安全设备的设计、制造、安装、使用、检测、维修、改造和报废应符合标准', 'https://www.wz.gov.cn/', '江苏金马公司被罚款60万元；项目经理罚款7.27万元；1名责任人被追刑责'),

('建筑施工', '中山翠亨电梯井口防护缺失致工人坠落身亡', '傲雷集团总部项目工地，劳务工人踩空摔落至电梯井基坑，被桩头钢筋贯穿致死。现场安全防护措施缺失，井口未设置防护栏杆和警示标识。', '高', '广东中山市', '翠亨新区', '2024-10-17', '1死', '现场安全防护措施缺失；电梯井口未设置防护栏杆和警示标识；钢筋端头未做防护处理', '电梯井口必须设置定型化防护门；预留洞口须加盖板并固定牢固；裸露钢筋端头须做弯折或加防护套', '《建筑施工高处作业安全技术规范》(JGJ 80)', 'https://www.sohu.com/a/902857611_161795', '劳务分包单位及主要负责人被行政处罚；总包和监理单位被移交住建部门处理'),

-- ========== 燃气安全 (6条) ==========
('燃气安全', '河北燕郊地埋天然气管道破损爆燃致7死27伤', '三河市燕郊镇，地铁盾构施工造成地埋天然气管道破损泄漏，燃气沿地下缝隙扩散至商住楼内聚集，遇点火源发生爆燃。四层商住建筑楼体坍塌，周边多栋住宅及车辆严重受损。', '高', '河北三河市', '燕郊镇', '2024-03-13', '7死27伤', '地铁盾构施工造成地埋天然气管道破损泄漏；燃气扩散至楼内聚集后遇点火源爆燃', '施工前必须查明地下管线分布并制定保护方案；建立燃气管道与轨道交通施工协调机制；加强燃气管网智能监测和泄漏预警', '《城镇燃气管理条例》第37条：建设工程施工范围内有地下燃气管线的，建设单位应会同施工单位与管道燃气经营者制定保护方案', 'https://baike.baidu.com/item/3·13燕郊燃气爆燃事故', '23名公职人员被追责；7名企业责任人被采取刑事强制措施'),

('燃气安全', '辽宁大石桥商铺液化气罐泄漏闪爆致4伤', '大石桥市金地佳园小区南门东侧一饭店，液化气罐泄漏引发闪爆，商铺门窗被震碎，两侧及对面住宅玻璃均有不同程度损伤。', '中', '辽宁大石桥市', '', '2024-09-13', '4伤', '液化气罐泄漏引发闪爆', '餐饮场所应安装可燃气体报警装置；液化气罐必须定期检验并在有效期内使用；用气完毕须关闭阀门', '《安全生产法》第36条：餐饮等行业使用燃气的应安装可燃气体报警装置', 'https://sdxw.iqilu.com/share/YS0yMS0xNTg4NjQ0OA.html', '商家被行政处罚并承担伤者医疗费用'),

('燃气安全', '哈尔滨香坊区液化气罐操作不当闪爆1死3伤', '香坊区古香街46号居民楼402室，居民使用液化石油气罐时操作不当发生闪爆，造成1人死亡、3人受伤，房屋结构受损。', '高', '黑龙江哈尔滨', '香坊区', '2024-05-23', '1死3伤', '液化石油气罐使用操作不当发生闪爆', '居民用气须定期检查减压阀和软管是否老化；发现燃气泄漏应立即开窗通风、关闭阀门、严禁动用明火；推广使用带熄火保护装置的燃气灶', '《城镇燃气管理条例》第27条：燃气用户应遵守安全用气规则', '', '当事人被行政处罚'),

('燃气安全', '沈阳苏家屯居民家中液化气爆燃1死3伤', '苏家屯某小区一居民家中，液化气罐发生爆燃，冲击波导致窗户飞出、墙体开裂，造成1人死亡、3人受伤。', '高', '辽宁沈阳市', '苏家屯区', '2024-04-10', '1死3伤', '液化气罐爆燃', '定期更换老化软管和减压阀；使用带自闭功能的合格减压阀；气瓶与灶具间距不小于1.5米', '《城镇燃气管理条例》；《液化石油气钢瓶》(GB 5842)', '', '当事人赔偿受害者损失'),

('燃气安全', '河南洛阳居民房煤气爆炸致丈夫92%烧伤后去世', '洛阳一居民房内煤气罐泄漏，住户未察觉，打火瞬间引发爆炸。丈夫烧伤面积92%经抢救无效死亡，妻子烧伤面积69%。', '高', '河南洛阳市', '', '2024-10-10', '1死1重伤', '煤气罐泄漏后打火引发爆炸', '使用燃气前应检查是否有泄漏（用肥皂水检测）；闻到燃气味立即通风、关闭阀门、不触动任何电器开关', '《城镇燃气管理条例》第27条', '', '事故调查报告移交司法机关处理'),

